/* Month-range filter. Appended to tcf-months.js by build_months.py, after the
   window.TCF_MONTHS literal. Loads after tcf-clusters(-EN).js and adds one row to
   its sticky toolbar: "Période / Period  [from] → [to]" plus presets. A prompt
   stays visible when at least one of the months it was listed under on the
   source falls inside the range. Every prompt also gets a thin "Vu en / Seen in"
   row listing those months, with the in-range ones highlighted.
   The range is kept in ?from=YYYY-MM&to=YYYY-MM and in localStorage, so it
   carries across pools and FR/EN. */
(function(){
  var D = window.TCF_MONTHS;
  function init(){
    var meta = document.querySelector('meta[name="tcf-set"]');
    var setKey = meta ? (meta.getAttribute("content") || "").trim() : "";
    var data = D && D.sets ? D.sets[setKey] : null;
    var sections = Array.prototype.slice.call(document.querySelectorAll("section.topic"));
    if (!data || !sections.length) return;
    var EN = (document.documentElement.lang || "").toLowerCase().indexOf("en") === 0;
    var T = EN ? {
      period: "Period", all: "All", last12: "Last 12 months", last6: "Last 6 months",
      seen: "Seen in", of: " of ", prompts: "prompts", boxes: "boxes", singles: "singles",
      answers: "answers to prepare", none: "No prompt in this period.",
      note: "Months = the monthly page of reussir-tcfcanada.com each prompt (or a reworded copy of it) was listed on.",
      mon: ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]
    } : {
      period: "Période", all: "Tout", last12: "12 derniers mois", last6: "6 derniers mois",
      seen: "Vu en", of: " sur ", prompts: "sujets", boxes: "blocs", singles: "isolés",
      answers: "réponses à préparer", none: "Aucun sujet sur cette période.",
      note: "Mois = la page mensuelle de reussir-tcfcanada.com où chaque sujet (ou une copie reformulée) a été publié.",
      mon: ["janv.","févr.","mars","avr.","mai","juin","juil.","août","sept.","oct.","nov.","déc."]
    };
    var ALL = D.months.slice();                       // ascending YYYY-MM
    function label(m){ var p = m.split("-"); return T.mon[+p[1] - 1] + " " + p[0]; }
    function shift(m, n){                             // m + n months
      var p = m.split("-"), t = +p[0] * 12 + (+p[1] - 1) + n;
      var y = Math.floor(t / 12), mo = t % 12 + 1;
      return y + "-" + (mo < 10 ? "0" : "") + mo;
    }
    function clamp(m){ return m < ALL[0] ? ALL[0] : (m > ALL[ALL.length - 1] ? ALL[ALL.length - 1] : m); }
    function valid(m){ return /^\d{4}-\d{2}$/.test(m || "") && ALL.indexOf(m) >= 0; }

    var store = { get: function(k){ try { return window.localStorage.getItem(k); } catch(e){ return null; } },
                  set: function(k, v){ try { window.localStorage.setItem(k, v); } catch(e){} } };

    // --- per-section months ------------------------------------------------
    var items = sections.map(function(s){
      var b = s.querySelector(".badge");
      var n = b ? parseInt((b.textContent || "").trim(), 10) : NaN;
      return { el: s, num: n, months: data[String(n)] || null };
    }).filter(function(it){ return !isNaN(it.num); });
    var byNum = {};
    items.forEach(function(it){ byNum[it.num] = it; });

    items.forEach(function(it){
      if (!it.months || !it.months.length) return;
      var row = document.createElement("div");
      row.className = "tcf-mrow";
      var lab = document.createElement("span");
      lab.className = "tcf-mrow-lab"; lab.textContent = T.seen;
      row.appendChild(lab);
      var years = {};
      it.months.forEach(function(m){ (years[m.slice(0, 4)] = years[m.slice(0, 4)] || []).push(m); });
      it.chips = [];
      Object.keys(years).sort().forEach(function(y){
        var g = document.createElement("span"); g.className = "tcf-my";
        var yb = document.createElement("b"); yb.textContent = y; g.appendChild(yb);
        years[y].forEach(function(m){
          var c = document.createElement("span");
          c.className = "tcf-mc"; c.textContent = T.mon[+m.slice(5) - 1];
          c.title = label(m);
          c.setAttribute("data-m", m);
          g.appendChild(c); it.chips.push(c);
        });
        row.appendChild(g);
      });
      var anchor = it.el.querySelector(".tcf-xref-row") || it.el.querySelector(".topic-head");
      if (anchor) anchor.parentNode.insertBefore(row, anchor.nextSibling);
    });

    // --- toolbar row -------------------------------------------------------
    injectStyle();
    var bar = document.querySelector(".tcf-clusterbar");
    var host = document.createElement("div");
    host.className = "tcf-mbar";
    var lab = document.createElement("span"); lab.className = "tcf-lab"; lab.textContent = T.period;
    function monthSelect(id){
      var s = document.createElement("select"); s.className = "tcf-select tcf-msel"; s.id = id;
      ALL.forEach(function(m){
        var o = document.createElement("option"); o.value = m; o.textContent = label(m); s.appendChild(o);
      });
      return s;
    }
    var selFrom = monthSelect("tcf-mfrom"), selTo = monthSelect("tcf-mto");
    selFrom.setAttribute("aria-label", T.period + " — " + (EN ? "from" : "de"));
    selTo.setAttribute("aria-label", T.period + " — " + (EN ? "to" : "à"));
    var arrow = document.createElement("span"); arrow.className = "tcf-marrow"; arrow.textContent = "→";
    var presets = document.createElement("span"); presets.className = "tcf-mpresets";
    var last = ALL[ALL.length - 1];
    [[T.all, ALL[0], last], [T.last12, clamp(shift(last, -11)), last], [T.last6, clamp(shift(last, -5)), last]]
      .forEach(function(p){
        var b = document.createElement("button"); b.type = "button"; b.className = "tcf-mpre";
        b.textContent = p[0];
        b.addEventListener("click", function(){ setRange(p[1], p[2]); });
        presets.appendChild(b);
      });
    var status = document.createElement("span"); status.className = "tcf-mstatus";
    var note = document.createElement("div"); note.className = "tcf-mnote"; note.textContent = T.note;
    host.appendChild(lab); host.appendChild(selFrom); host.appendChild(arrow); host.appendChild(selTo);
    host.appendChild(presets); host.appendChild(status); host.appendChild(note);
    if (bar){
      var desc = bar.querySelector(".tcf-desc");
      bar.insertBefore(host, desc || null);
    } else {
      host.classList.add("tcf-mbar-solo");
      sections[0].parentNode.insertBefore(host, sections[0]);
    }
    var empty = document.createElement("p"); empty.className = "tcf-mempty"; empty.textContent = T.none;
    host.parentNode.insertBefore(empty, host.nextSibling);

    // --- range state -------------------------------------------------------
    var range = { from: ALL[0], to: last };
    (function(){
      var q = new URLSearchParams(window.location.search);
      var f = q.get("from"), t = q.get("to"), fromUrl = valid(f) || valid(t);
      if (!fromUrl){
        var saved = (store.get("tcf-months:range") || "").split("..");
        f = saved[0]; t = saved[1];
      }
      if (valid(f)) range.from = f;
      if (valid(t)) range.to = t;
      if (range.from > range.to){ var x = range.from; range.from = range.to; range.to = x; }
      if (fromUrl) store.set("tcf-months:range", range.from + ".." + range.to);
    })();

    function setRange(f, t){
      if (f > t){ var x = f; f = t; t = x; }
      range.from = f; range.to = t;
      store.set("tcf-months:range", f + ".." + t);
      var q = new URLSearchParams(window.location.search);
      if (f === ALL[0] && t === last){ q.delete("from"); q.delete("to"); }
      else { q.set("from", f); q.set("to", t); }
      var qs = q.toString();
      try { history.replaceState(null, "", window.location.pathname + (qs ? "?" + qs : "") + window.location.hash); } catch(e){}
      apply();
    }
    selFrom.addEventListener("change", function(){ setRange(selFrom.value, selTo.value); });
    selTo.addEventListener("change", function(){ setRange(selFrom.value, selTo.value); });

    function inRange(m){ return m >= range.from && m <= range.to; }

    function apply(){
      selFrom.value = range.from; selTo.value = range.to;
      var active = !(range.from === ALL[0] && range.to === last);
      document.body.classList.toggle("tcf-mfilter-on", active);
      var shown = 0;
      items.forEach(function(it){
        var keep = !active || !it.months || it.months.some(inRange);
        it.el.classList.toggle("tcf-mout", !keep);
        it.out = !keep;
        if (keep) shown++;
        (it.chips || []).forEach(function(c){ c.classList.toggle("tcf-min", active && inRange(c.getAttribute("data-m"))); });
      });
      var boxes = 0, singles = 0;
      document.querySelectorAll(".tcf-group").forEach(function(g){
        var secs = g.querySelectorAll("section.topic"), any = false;
        for (var i = 0; i < secs.length; i++) if (!secs[i].classList.contains("tcf-mout")) { any = true; break; }
        g.classList.toggle("tcf-gout", !any);
        if (any) boxes++;
        var cores = g.querySelectorAll(".tcf-core");
        for (var c = 0; c < cores.length; c++){
          var cs = cores[c].querySelectorAll("section.topic"), cAny = false;
          for (var j = 0; j < cs.length; j++) if (!cs[j].classList.contains("tcf-mout")) { cAny = true; break; }
          cores[c].classList.toggle("tcf-cout", !cAny);
        }
        var seams = g.querySelectorAll(".tcf-seam");
        for (var k = 0; k < seams.length; k++){
          var p = seams[k].previousElementSibling, n = seams[k].nextElementSibling;
          seams[k].classList.toggle("tcf-sout",
            !!((p && p.classList.contains("tcf-cout")) || (n && n.classList.contains("tcf-cout"))));
        }
      });
      items.forEach(function(it){
        if (it.out) return;
        var g = it.el.parentNode;
        while (g && g !== document.body && !(g.classList && g.classList.contains("tcf-group"))) g = g.parentNode;
        if (!g || g === document.body) singles++;
      });
      links();
      status.textContent = active
        ? shown + T.of + items.length + " " + T.prompts + " · " + (boxes + singles) + " " + T.answers
          + (boxes ? " (" + boxes + " " + T.boxes + " + " + singles + " " + T.singles + ")" : "")
        : items.length + " " + T.prompts + " · " + label(ALL[0]) + " → " + label(last);
      empty.style.display = active && !shown ? "" : "none";
    }
    function links(){
      document.querySelectorAll(".tcf-link").forEach(function(l){
        var a = byNum[+l.getAttribute("data-a")], b = byNum[+l.getAttribute("data-b")];
        l.classList.toggle("tcf-lout", !!((a && a.out) || (b && b.out)));
      });
    }
    // Sort changes rebuild the similarity links; re-mark them when #tcf-flow changes.
    var flow = document.getElementById("tcf-flow");
    if (flow && window.MutationObserver){
      new MutationObserver(function(){ links(); }).observe(flow, { childList: true });
    }
    apply();

    function injectStyle(){
      if (document.getElementById("tcf-months-style")) return;
      var css = ""
      + ".tcf-mbar{display:flex;align-items:center;gap:.45rem;flex-wrap:wrap;margin:.5rem 0 0;"
      + "padding:.45rem 0 0;border-top:1px dashed var(--line,#e4e7ec)}"
      + ".tcf-mbar-solo{border:1px solid var(--line,#e4e7ec);border-radius:12px;padding:.6rem .8rem;margin:0 0 1rem}"
      + ".tcf-msel{font-size:.85rem;padding:.22rem .4rem}"
      + ".tcf-marrow{color:var(--muted,#5b6470)}"
      + ".tcf-mpresets{display:inline-flex;gap:.3rem;flex-wrap:wrap}"
      + ".tcf-mpre{font:inherit;font-size:.74rem;cursor:pointer;color:var(--muted,#5b6470);"
      + "border:1px solid var(--line,#e4e7ec);background:#f6f8fb;border-radius:999px;padding:.12rem .55rem}"
      + ".tcf-mpre:hover{border-color:var(--accent,#2563eb);color:var(--accent,#2563eb)}"
      + ".tcf-mstatus{font-size:.8rem;color:var(--muted,#5b6470);margin-left:auto}"
      + "body.tcf-mfilter-on .tcf-mstatus{color:#0b4f8a;font-weight:600}"
      + ".tcf-mnote{flex:0 0 100%;font-size:.7rem;color:var(--muted,#5b6470);display:none}"
      + "body.tcf-mfilter-on .tcf-mnote{display:block}"
      + ".tcf-mempty{margin:1rem 0;padding:.8rem 1rem;border:1px dashed var(--line,#e4e7ec);border-radius:12px;"
      + "color:var(--muted,#5b6470);font-size:.9rem}"
      + ".tcf-mrow{display:flex;flex-wrap:wrap;align-items:baseline;gap:.15rem .55rem;margin:.15rem 0 .1rem 2.6rem;"
      + "font-size:.68rem;line-height:1.35;color:#8a94a3}"
      + ".tcf-mrow-lab{letter-spacing:.02em}"
      + ".tcf-my{display:inline-flex;gap:.25rem;align-items:baseline;white-space:nowrap}"
      + ".tcf-my b{font-weight:600;color:#6b7482}"
      + ".tcf-mc{border-radius:4px;padding:0 .15rem}"
      + ".tcf-mc.tcf-min{background:#dbeafe;color:#0b4f8a;font-weight:600}"
      // the toolbar is sticky: keep this row short on phones
      + "@media (max-width:520px){.tcf-mrow{margin-left:0}.tcf-mstatus{margin-left:0;flex:0 0 100%;font-size:.74rem}"
      + ".tcf-mpre:not(:first-child),body.tcf-mfilter-on .tcf-mnote{display:none}}"
      + ".tcf-mout,.tcf-gout,.tcf-cout,.tcf-sout,.tcf-lout{display:none!important}";
      var st = document.createElement("style");
      st.id = "tcf-months-style"; st.textContent = css;
      document.head.appendChild(st);
    }
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
